}

#include <iostream>
#include <memory>
#include <utility>

struct Item {
  int value = 7;
  ~Item() { std::cout << "release\n"; }
};

int main() {
  auto p = std::make_unique<Item>();
  (void)std::move(p);  // 没有接收者，只丢弃这个表达式
  std::cout << (p != nullptr) << '\n';

  {
    auto q = std::move(p);
    std::cout << (p == nullptr) << '\n';
    std::cout << q->value << '\n';
  }  // q 释放 Item
  std::cout << "outside\n";
}

