answer:
class LRU {
  size_t cap_;
  std::list<std::pair<int,int>> items_;
  std::unordered_map<int,decltype(items_)::iterator> index_;
public:
  explicit LRU(size_t cap):cap_(cap){}
  int get(int key) {
    auto it=index_.find(key);
    if(it==index_.end()) return -1;
    items_.splice(items_.begin(),items_,it->second);
    return it->second->second;
  }
  void put(int key,int value) {
    if(cap_==0) return;
    auto it=index_.find(key);
    if(it!=index_.end()) { it->second->second=value; items_.splice(items_.begin(),items_,it->second); return; }
    if(items_.size()==cap_) { index_.erase(items_.back().first); items_.pop_back(); }
    items_.emplace_front(key,value); index_[key]=items_.begin();
  }
};

